+            },
+            "properties": {
+              "complete": true
+            }
+          }
+        },
+        "{city=Antwerp}": {
+          "key": {
+            "city": "Antwerp"
+          },
+          "doc_count": 3,
+          "museum_tour": {
+            "type": "Feature",
+            "geometry": {
+              "coordinates": [ [ 4.401384, 51.220292 ], [ 4.405819, 51.221758 ], [ 4.4052, 51.2229 ] ],
+              "type": "LineString"
+            },
+            "properties": {
+              "complete": true
+            }
+          }
+        },
+        "{city=Amsterdam}": {
+          "key": {
+            "city": "Amsterdam"
+          },
+          "doc_count": 5,
+          "museum_tour": {
+            "type": "Feature",
+            "geometry": {
+              "coordinates": [ [ 4.889187, 52.373184 ], [ 4.885057, 52.370159 ], [ 4.901618, 52.369219 ], [ 4.91235, 52.374081 ], [ 4.914722, 52.371667 ] ],
+              "type": "LineString"
+            },
+            "properties": {
+              "complete": true
+            }
+          }
+        }
+      }
