+  "aggregations": {
+    "path": {
+      "terms": {"field": "city"},
+      "aggregations": {
+        "museum_tour": {
+          "geo_line": {
+            "point": {"field": "location"},
+            "sort": {"field": "@timestamp"}
+          }
+        }
+      }
+    }
+  }
+}
+----
+// TEST[continued]
+
