+            final CheckedRunnable<Exception> afterIndexShardRecoveryRunner = () -> assertNull(
+                PlainActionFuture.<Void, Exception>get(fut -> indexEventListener.afterIndexShardRecovery(shard, fut), 10, TimeUnit.SECONDS)
+            );
