+        }
+
+        @Override
+        public final boolean equals(Object o) {
+            return sameClassAs(o);
+        }
+
+        @Override
+        public final int hashCode() {
+            return classHash();
+        }
+
+        @Override
+        public final void visit(QueryVisitor visitor) {
+            visitor.visitLeaf(this);
+        }
+    }
