+    }
+
+    private boolean isValidForInput(Object input) {
+        if (this == EXACT) {
+            return input instanceof String || input instanceof Number;
+        } else if (List.of(FUZZY, PREFIX, SUFFIX, CONTAINS).contains(this)) {
+            return input instanceof String;
