+                            docs.appendInt(doc);
+                        }
+                        pages.add(
+                            new Page(
+                                new DocVector(
+                                    IntBlock.newConstantBlockWith(0, end - begin).asVector(),
+                                    IntBlock.newConstantBlockWith(ctx.ord, end - begin).asVector(),
+                                    docs.build(),
+                                    true
+                                ).asBlock()
+                            )
+                        );
+                        docs = IntVector.newVectorBuilder(BLOCK_LENGTH);
+                        begin = end;
+                    }
+                }
+            }
