+
+        ChunkedToXContent outerChunkedContent = params -> Iterators.concat(
+            ChunkedToXContentHelper.field("field3", 10),
+            ChunkedToXContentHelper.field("field4", innerChunkedContent, EMPTY_PARAMS)
