+        assertThat(((Map<String, Object>) mappingProperties.get("numeric_field")).get("type"), equalTo("integer"));
+        assertThat(
+            ((Map<String, Object>) mappingProperties.get("socket")).get("properties"),
+            equalTo(Map.of("ip", Map.of("type", "keyword")))
